const resp = $json;
if (resp.ok !== true) {
  const runId = $('Build Run Params').item.json.run_id;
  throw new Error(`m4 seed failed for run ${runId}: ${resp.error || 'module API returned ok:false with no error message'}`);
}
return [{ json: resp }];

