const params = $('Build Run Params').item.json;
const sync = $('Call Module API - Sync').item.json;
const analyze = $('Call Module API - Analyze').item.json;
const render = $('Call Module API - Render').item.json;
const base = $env.MODULE_API_URL;

const summary = {
  run_id: params.run_id,
  event_slug: params.event_slug,
  sync: sync.summary || {},
  analyze: analyze.summary || {},
  render: render.summary || {},
  dashboard_url: `${base}/dashboard/${params.run_id}/`,
  narrative_refresh_url: `${base}/narrative/${params.run_id}?refresh=1`,
  finished_at: new Date().toISOString()
};

return [{ json: summary }];
